#!/usr/bin/env python3
"""Linux host/32-bit regression for exact production directory parsers and file refresh.
Only transport identity and clock/path lookup are mocked. No network or game is launched.
"""
import argparse,pathlib,subprocess,tempfile,sys
parser=argparse.ArgumentParser();parser.add_argument("--cc",default="gcc");parser.add_argument("--m32",action="store_true");args=parser.parse_args()
root=pathlib.Path(__file__).resolve().parents[1]
prod=(root/"port/linux/src/community_directory.c").read_text()
start=prod.index("struct cursor {");end=prod.index("/* Test-only directory transport.")
prefix='\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <strings.h>\n#include <stdint.h>\n#include <errno.h>\n#include <fcntl.h>\n#include <assert.h>\n#include <sys/stat.h>\n#include <unistd.h>\n#include "p2p.h"\n#include "community_directory.h"\n#include "directory_cache_state.h"\n#include "directory_snapshot_id.h"\n#define MAX_GAMES 512\n#define LIMIT (1024*1024)\n#define P2P_KEY_HASH_SIZE 32\n#include "posix.h"\ntypedef unsigned long long Uint64;\nstatic void p2p_identifier_from_hash(const unsigned char *hash,unsigned char *id){memcpy(id,hash,6);}\nstatic struct community_directory_game classic_games[2][MAX_GAMES];\nstatic int classic_count[2],classic_loaded[2],classic_total[2],classic_failed[2];\nstatic time_t classic_mtime[2];\nstatic Uint64 classic_next_check;\nstatic Uint64 fixture_ticks;\nstatic char fixture_exe[1024];\nstatic Uint64 SDL_GetTicks(void){return fixture_ticks;}\nstatic int update_executable_path(char *out,size_t cap){snprintf(out,cap,"%s",fixture_exe);return 1;}\n'
checks='static void write_feed(char const *dir,char const *name,char const *text){\n char path[1200];snprintf(path,sizeof(path),"%s/%s",dir,name);\n FILE*f=fopen(path,"wb");assert(f);assert(fwrite(text,1,strlen(text),f)==strlen(text));assert(fclose(f)==0);\n}\nint main(void){\n struct community_directory_game rows[MAX_GAMES];int total,n;char out[128],d[]="/tmp/halo-directory-unit-XXXXXX",path[1200];\n assert(mkdtemp(d));snprintf(fixture_exe,sizeof(fixture_exe),"%s/halo",d);\n assert(parse_classic_feed("[]",2,rows,0,&total)==0&&total==0);\n char*large=calloc(1,100000);assert(large);strcat(large,"[");\n for(int i=0;i<514;i++){if(i)strcat(large,",");strcat(large,"{\\"address\\":\\"127.0.0.7\\",\\"port\\":2302,\\"game\\":\\"haloce\\"}");}\n strcat(large,"]");n=parse_classic_feed(large,strlen(large),rows,0,&total);assert(n==512&&total==514);\n assert(rows[0].version==-2&&!rows[0].listing.open);\n unsigned char id_a[6],id_b[6],id_repeat[6];\n directory_snapshot_identifier("127.0.0.1:2302",0,id_a);directory_snapshot_identifier("127.0.0.1:2302",0,id_repeat);assert(!memcmp(id_a,id_repeat,6));\n directory_snapshot_identifier("127.0.0.2:2302",0,id_b);assert(memcmp(id_a,id_b,6));\n directory_snapshot_identifier("127.0.0.1:2302",1,id_b);assert(memcmp(id_a,id_b,6));\n unsigned char rowkeys[3][6];int vers[3]={-2,-2,-3};memcpy(rowkeys[0],id_b,6);memcpy(rowkeys[1],id_a,6);memcpy(rowkeys[2],id_a,6);\n assert(directory_selection_index(id_a,-2,rowkeys[0],vers,3,6)==1);assert(directory_selection_index(id_a,-3,rowkeys[0],vers,3,6)==2);assert(directory_selection_index(id_a,21,rowkeys[0],vers,3,6)==-1);\n assert(directory_selection_index(id_a,-2,rowkeys[0],vers,0,6)==-1);\n char const*good="[{\\"address\\":\\"127.0.0.9\\",\\"port\\":2302}]";\n write_feed(d,"halo-ce-master.json",good);write_feed(d,"halo-pc-master.json","[]");\n fixture_ticks=3000;refresh_classic();assert(classic_count[0]==1&&classic_total[0]==1&&classic_loaded[0]&&!classic_failed[0]);\n assert(classic_count[1]==0&&classic_loaded[1]&&!classic_failed[1]);\n snprintf(path,sizeof(path),"%s/halo-ce-master.json",d);assert(unlink(path)==0);\n fixture_ticks+=3000;refresh_classic();assert(classic_count[0]==1&&classic_failed[0]&&classic_loaded[0]);\n write_feed(d,"halo-ce-master.json","[{\\"address\\":\\"127.0.0.4\\",\\"port\\":2302},");fixture_ticks+=3000;refresh_classic();\n assert(classic_count[0]==1&&classic_failed[0]);assert(strstr(classic_games[0][0].listing.name,"127.0.0.9"));\n write_feed(d,"halo-pc-master.json",large);fixture_ticks+=3000;refresh_classic();assert(classic_count[1]==512&&classic_total[1]==514&&!classic_failed[1]);assert(classic_games[1][0].version==-3);\n write_feed(d,"halo-ce-master.json","[{\\"address\\":\\"127.0.0.8\\",\\"port\\":2302}]");fixture_ticks+=3000;refresh_classic();assert(!classic_failed[0]&&strstr(classic_games[0][0].listing.name,"127.0.0.8"));\n FILE*f=fopen(path,"wb");assert(f);assert(ftruncate(fileno(f),LIMIT+1)==0);fclose(f);fixture_ticks+=3000;refresh_classic();assert(classic_failed[0]&&classic_count[0]==1&&strstr(classic_games[0][0].listing.name,"127.0.0.8"));\n write_feed(d,"halo-ce-master.json",good);fixture_ticks+=3000;refresh_classic();assert(!classic_failed[0]);\n struct stat preserved;assert(stat(path,&preserved)==0);\n write_feed(d,"halo-ce-master.json","[{\\"address\\":\\"127.0.0.6\\",\\"port\\":2302}]");\n struct timespec times[2]={preserved.st_atim,preserved.st_mtim};assert(utimensat(AT_FDCWD,path,times,0)==0);\n fixture_ticks+=3000;refresh_classic();assert(strstr(classic_games[0][0].listing.name,"127.0.0.6"));\n const char*empty="{\\"games\\":[]}";assert(parse_feed(empty,strlen(empty),rows,&total)==0&&total==0);\n const char*bad="{\\"other\\":[]}";assert(parse_feed(bad,strlen(bad),rows,&total)==-1);\n const char*dupe="{\\"games\\":[],\\"games\\":[]}";assert(parse_feed(dupe,strlen(dupe),rows,&total)==-1);\n struct directory_cache_state state={0};directory_cache_status(&state,0,out,sizeof(out));assert(strstr(out,"not been checked"));\n directory_snapshot_status("CE",1,1,1,1,2,out,sizeof(out));assert(strstr(out,"cached"));\n free(large);unlink(path);snprintf(path,sizeof(path),"%s/halo-pc-master.json",d);unlink(path);rmdir(d);\n puts("PASS actual production parsers and refresh: classic514 truncation, deleted/truncated/oversize atomic cache retention, recovery, empty/missing/duplicate native games");\n}\n'
with tempfile.TemporaryDirectory(prefix="halo-directory-source-test-") as tmp:
    source=pathlib.Path(tmp)/"test.c";exe=pathlib.Path(tmp)/"test"
    source.write_text(prefix+prod[start:end]+checks)
    command=[args.cc]+(["-m32","-malign-double"] if args.m32 else [])+["-Wall","-Wextra","-Werror","-Wno-misleading-indentation","-I"+str(root/"port/linux/src"),str(source),"-o",str(exe)]
    bridge=pathlib.Path(tmp)/"posix_files.o"
    # Host bridge uses the host ABI, independently of the game alignment.
    subprocess.run([args.cc]+(["-m32"] if args.m32 else [])+["-D_GNU_SOURCE","-D_FILE_OFFSET_BITS=64","-I"+str(root/"port/linux/src"),"-c",str(root/"port/linux/src/posix_files.c"),"-o",str(bridge)],check=True)
    command.insert(-2,str(bridge))
    subprocess.run(command,check=True);subprocess.run([str(exe)],check=True)
